import json, subprocess, sys, random, re
sys.setrecursionlimit(1000000)

def run(reqs):
    data=b'\n'.join(json.dumps(r).encode() for r in reqs)
    p=subprocess.run([sys.executable,"-I","/app/submission/main.py"],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
    if p.returncode!=0: print("RC",p.returncode,p.stderr.decode());sys.exit(1)
    return [json.loads(x) for x in p.stdout.splitlines()]

def expected(inputs,states,edges,start,fair):
    P=len(inputs);R=len(inputs[0]) if P else 0;D=len(inputs[0][0]) if R else 0
    exp=[]
    for q in range(R):
        v=[0]*D
        for r in range(P):
            for i in range(D): v[i]+=inputs[r][q][i]
        exp.append(v)
    def safe(st):
        for r in range(P):
            for q,vec in enumerate(st["delivered"][r]):
                if vec!=exp[q]:return False
        for s in st["slots"]:
            q=s["seq"];acc=[0]*D
            for rr in s["ranks"]:
                for i in range(D): acc[i]+=inputs[rr][q][i]
            if acc!=s["sum"]:return False
        return True
    def done(st):
        return all(len(st["delivered"][r])==R for r in range(P))
    names=sorted(set([e[1] for e in edges])|set(f["action"] for f in fair))
    idx={nm:i+1 for i,nm in enumerate(names)}
    exp_edges=set((e[0],idx[e[1]],e[2]) for e in edges)
    wf=set(idx[f["action"]] for f in fair if f["mode"]=="weak")
    sf=set(idx[f["action"]] for f in fair if f["mode"]=="strong")
    safeS=set(i for i in range(len(states)) if safe(states[i]))
    doneS=set(i for i in range(len(states)) if done(states[i]))
    return names,exp_edges,wf,sf,safeS,doneS,len(states),start

def parse_module(mod):
    lines=[l.strip() for l in mod.splitlines() if l.strip()]
    assert lines[0]=="---- MODULE ModelData ----", lines[0]
    assert lines[-1]=="====", lines[-1]
    assert lines[1]=="EXTENDS Integers, Sequences, FiniteSets"
    defs={}
    order=[]
    for l in lines[2:-1]:
        m=re.match(r"^(\w+) == (.+)$", l)
        assert m, l
        defs[m.group(1)]=m.group(2); order.append(m.group(1))
    assert order==["Nodes","Initial","Edges","ActionNames","WFIds","SFIds","SafeNodes","DoneNodes"], order
    return defs

def parse_set_triples(s):
    s=s.strip()
    assert s.startswith("{") and s.endswith("}")
    inner=s[1:-1].strip()
    if not inner: return set()
    parts=re.findall(r"<<\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*>>",inner)
    res=set((int(a),int(b),int(c)) for a,b,c in parts)
    # ensure nothing else
    return res

def parse_set_ints(s):
    s=s.strip(); assert s.startswith("{") and s.endswith("}")
    inner=s[1:-1].strip()
    if not inner: return set()
    return set(int(x) for x in inner.split(","))

def parse_tuple(s):
    s=s.strip(); assert s.startswith("<<") and s.endswith(">>")
    inner=s[2:-2].strip()
    if not inner: return []
    return [x.strip() for x in inner.split(",")]

